int minDifficulty(std::vector<int>& jobDifficulty, int d) {
    int n = jobDifficulty.size();
    if (n < d) return -1;
    std::vector<std::vector<int>> dp(d, std::vector<int>(n, INT_MAX));

    dp[0][0] = jobDifficulty[0];
    for (int i = 1; i < n; ++i) {
        dp[0][i] = std::max(dp[0][i-1], jobDifficulty[i]);
    }

    for (int i = 1; i < d; ++i) {
        for (int j = i; j < n; ++j) {
            int maxD = jobDifficulty[j];
            for (int k = j; k >= i; --k) {
                maxD = std::max(maxD, jobDifficulty[k]);
                dp[i][j] = std::min(dp[i][j], dp[i-1][k-1] + maxD);
            }
        }
    }
    return dp[d-1][n-1];
}

int minDifficultyWithStart(std::vector<int>& jobDifficulty, int d, int start) {
    int n = jobDifficulty.size();
    if (n < d) return -1;
    std::vector<std::vector<int>> dp(d, std::vector<int>(n, INT_MAX));

    dp[0][start] = jobDifficulty[start];
    for (int i = start + 1; i < n; ++i) {
        dp[0][i] = std::max(dp[0][i-1], jobDifficulty[i]);
    }

    for (int i = 1; i < d; ++i) {
        for (int j = i + start; j < n; ++j) {
            int maxD = jobDifficulty[j];
            for (int k = j; k >= i + start; --k) {
                maxD = std::max(maxD, jobDifficulty[k]);
                dp[i][j] = std::min(dp[i][j], dp[i-1][k-1] + maxD);
            }
        }
    }
    return dp[d-1][n-1];
}

