public int[] kthSmallestPair(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[k + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = k; j >= 1; j--) {
            if (j > i * (i - 1) / 2) {
                continue;
            }
            for (int l = 0; l < i; l++) {
                dp[j] = Math.min(dp[j], dp[j - (i - l)] + nums[l]);
