class Graph {
    private int V;
    private List<Integer>[] adjList;

    public Graph(int V) {
        this.V = V;
        adjList = new List[V];
        for (int i = 0; i < V; i++) {
            adjList[i] = new ArrayList<>();
        }
    }

    public void addEdge(int u, int v) {
        adjList[u].add(v);
    }

    public List<Integer>[] getAdjList() {
        return adjList;
    }
}

class TopologicalSort {
    private int V;
    private List<Integer>[] adjList;
    private boolean[] visited;
    private Stack<Integer> stack;

    public TopologicalSort(Graph graph) {
        this.V = graph.getAdjList().length;
        this.adjList = graph.getAdjList();
        visited = new boolean[V];
        stack = new Stack<>();
    }

    public boolean isDAG() {
        for (int i = 0; i < V; i++) {
            if (!visited[i]) {
                if (!dfs(i)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean dfs(int u) {
        visited[u] = true;
        for (int v : adjList[u]) {
            if (!visited[v]) {
                if (!dfs(v)) {
                    return false;
                }
            } else if (stack.contains(v)) {
                return false;
            }
        }
        stack.push(u);
        return true;
    }

    public Stack<Integer> getStack() {
        return stack;
    }
}

