    Stack<Integer> st = new Stack<>();
    for (char c : s.toCharArray()) {
        if (Character.isDigit(c)) {
            num = num * 10 + (c - '0');
        } else {
            result += sign * num;
            num = 0;
            if (c == '+') {
                sign = 1;
            } else if (c == '-') {
                sign = -1;
            } else if (c == '(') {
                st.push(result);
                st.push(sign);
                result = 0;
                sign = 1;
            } else if (c == ')') {
                int prev_sign = st.pop();
                int prev_result = st.pop();
                result = prev_result + prev_sign * result;
            }
        }
    }
    result += sign * num;
    return result;
}
