class Solution {
    public int[][] solve(int[][] rooms) {
        if (rooms.length == 0) return new int[0][0];
        int m = rooms.length, n = rooms[0].length;

        for (int i = 0; i < m; ++i) {
            dfs(rooms, i, 0);
            dfs(rooms, i, n - 1);
        }
        for (int i = 0; i < n; ++i) {
            dfs(rooms, 0, i);
            dfs(rooms, m - 1, i);
        }
        return rooms;
    }

    private void dfs(int[][] rooms, int x, int y) {
        if (x < 0 || x >= rooms.length || y < 0 || y >= rooms[0].length || rooms[x][y] == -1) {
            return;
        }
        int val = rooms[x][y];
        rooms[x][y] = -1;
        dfs(rooms, x - 1, y);
        dfs(rooms, x + 1, y);
        dfs(rooms, x, y - 1);
