    dp[0][0] = 1;

    for (int i = 1; i <= m; i++) {
        for (int j = 0; j <= n; j++) {
            dp[i][j] = dp[i - 1][j];
            if (j > 0) dp[i][j] += dp[i - 1][j - 1];
        }
    }

    int ans = 0;
    for (String str : strs) {
        int ones = 0, zeros = 0;
        for (char c : str.toCharArray()) {
            if (c == '1') ones++;
            else zeros++;
        }

        if (ones > m || zeros > n) continue;
        ans += dp[m - ones][n - zeros];
    }

    return ans;
}

